+
+    public ContactView(MessageStore messageStore) {
+        this.messageStore = messageStore;
+
+        add(new H1("Contact"));
+        add(new RouterLink("About", AboutView.class));
+
+        FormLayout form = new FormLayout();
+        form.add(name, email, phone);
+        form.add(message);
+        form.add(send);
+
+        messageGrid.addColumn(Message::name).setHeader("Name");
+        messageGrid.addColumn(Message::message).setHeader("Message");
+        messageGrid.setItems(messageStore.getMessages());
+        messageGrid.setWidthFull();
+
+        add(form, messageGrid);
+        setWidthFull();
+
+        send.addClickListener(event -> sendMessage());
+        send.addClickShortcut(Key.ENTER);
+        addEditListeners();
+    }
+
+    private void addEditListeners() {
+        name.addValueChangeListener(event -> edited(name));
+        email.addValueChangeListener(event -> edited(email));
+        phone.addValueChangeListener(event -> edited(phone));
+        message.addValueChangeListener(event -> edited(message));
+
+        name.addKeyDownListener(Key.ENTER, event -> sendIfEnabled());
+        email.addKeyDownListener(Key.ENTER, event -> sendIfEnabled());
+        phone.addKeyDownListener(Key.ENTER, event -> sendIfEnabled());
+        message.addKeyDownListener(Key.ENTER, event -> sendIfEnabled());
+    }
+
+    private void sendIfEnabled() {
+        if (send.isEnabled()) {
+            sendMessage();
+        }
+    }
+
+    private void edited(Component field) {
+        if (!resetting) {
+            send.setEnabled(true);
+            if (field instanceof TextField textField) {
+                textField.setInvalid(false);
+            } else if (field instanceof EmailField emailField) {
+                emailField.setInvalid(false);
+            } else if (field instanceof TextArea textArea) {
+                textArea.setInvalid(false);
+            }
+        }
+    }
